function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'DinnerPlates' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with DinnerPlates(capacity).';
  const capacity = args[0][0];
  if (!Number.isInteger(capacity) || capacity < 1 || capacity > 20000) return 'capacity is a whole number from 1 to 2 * 10^4.';
  if (operations.length - 1 > 200000) return 'At most 2 * 10^5 calls to push, pop and popAtStack.';
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'push') {
      if (a.length !== 1 || !Number.isInteger(a[0]) || a[0] < 1 || a[0] > 20000) return 'push takes one value from 1 to 2 * 10^4.';
    } else if (operations[i] === 'pop') {
      if (a.length !== 0) return 'pop takes no arguments.';
    } else if (operations[i] === 'popAtStack') {
      if (a.length !== 1 || !Number.isInteger(a[0]) || a[0] < 0 || a[0] > 100000) return 'popAtStack takes one index from 0 to 10^5.';
    } else {
      return 'Only push, pop and popAtStack can follow the constructor.';
    }
  }
  return null;
}

