class DinnerPlates {
  constructor(capacity) {
    this.capacity = capacity;
    this.stacks = [];
    this.open = [];
  }

  push(val) {
    while (this.open.length > 0 && this.open[0] >= this.stacks.length) {
      this.takeOpen();
    }
    if (this.open.length === 0) {
      this.addOpen(this.stacks.length);
      this.stacks.push([]);
    }
    const stack = this.stacks[this.open[0]];
    stack.push(val);
    if (stack.length === this.capacity) {
      this.takeOpen();
    }
  }

  pop() {
    return this.popAtStack(this.stacks.length - 1);
  }

  popAtStack(index) {
    const stack = this.stacks[index];
    if (stack === undefined || stack.length === 0) {
      return -1;
    }
    if (stack.length === this.capacity) {
      this.addOpen(index);
    }
    const val = stack.pop();
    while (this.stacks.length > 0 && this.stacks[this.stacks.length - 1].length === 0) {
      this.stacks.pop();
    }
    return val;
  }

  addOpen(index) {
    const heap = this.open;
    heap.push(index);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent] <= heap[child]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  }

  takeOpen() {
    const heap = this.open;
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const left = 2 * parent + 1;
      let smallest = parent;
      if (left < heap.length && heap[left] < heap[smallest]) smallest = left;
      if (left + 1 < heap.length && heap[left + 1] < heap[smallest]) smallest = left + 1;
      if (smallest === parent) break;
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
  }
}

