function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const capacity = large ? (rand() < 0.3 ? int(1, 3) : rand() < 0.5 ? int(4, 40) : 20000) : int(1, 4);
  const maxVal = rand() < 0.5 ? 20 : 20000;
  const calls = large ? 499 : int(1, 18);
  const pushRate = 0.35 + rand() * 0.35;
  const popRate = 0.1 + rand() * 0.3;
  const operations = ['DinnerPlates'];
  const args = [[capacity]];
  let plates = 0;
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < pushRate) {
      operations.push('push');
      args.push([int(1, maxVal)]);
      plates++;
    } else if (roll < pushRate + popRate) {
      operations.push('pop');
      args.push([]);
    } else {
      const reach = Math.max(1, Math.ceil(plates / capacity) + 1);
      operations.push('popAtStack');
      args.push([rand() < 0.05 ? int(0, 100000) : int(0, reach)]);
    }
  }
  return [operations, args];
}
